import SwiftUI
import AppKit

final class AppDelegate: NSObject, NSApplicationDelegate {
    func applicationShouldTerminateAfterLastWindowClosed(_ sender: NSApplication) -> Bool { true }
}

@main
struct QDLApp: App {
    @NSApplicationDelegateAdaptor(AppDelegate.self) private var appDelegate
    @StateObject private var model = AppModel()

    var body: some Scene {
        WindowGroup("QDL") {
            RootView()
                .environmentObject(model)
                .frame(minWidth: 1120, minHeight: 700)
        }
        .windowStyle(.hiddenTitleBar)
        .defaultSize(width: 1280, height: 840)
        .commands {
            CommandGroup(replacing: .appSettings) {
                Button("Qobuz Account…") { model.showAccount = true }
                    .keyboardShortcut(",", modifiers: .command)
                Button("Appearance…") { model.showAppearance = true }
                    .keyboardShortcut(",", modifiers: [.command, .option])
                Button("Update Download Engine") { Task { await model.updateEngine() } }
                    .disabled(model.isRunning)
            }
            CommandGroup(replacing: .newItem) {}
            CommandGroup(after: .pasteboard) {
                Divider()
                Button("Paste and Open Link") { model.pasteAndOpen() }
                    .keyboardShortcut("v", modifiers: [.command, .shift])
            }
            CommandMenu("Go") {
                Button("Browse") { model.pane = .browse }
                    .keyboardShortcut("1", modifiers: .command)
                Button("Downloads") { model.pane = .downloads }
                    .keyboardShortcut("2", modifiers: .command)
            }
        }
    }
}

