import Foundation
import CryptoKit

// MARK: - Locations

enum Paths {
    static let support: URL = {
        let base = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0]
        let dir = base.appendingPathComponent("QDL", isDirectory: true)
        try? FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        return dir
    }()

    /// QDL keeps its own streamrip config so it never touches one you set up by hand.
    static var config: URL { support.appendingPathComponent("streamrip.toml") }

    static var defaultStreamripConfig: URL {
        FileManager.default.homeDirectoryForCurrentUser
            .appendingPathComponent("Library/Application Support/streamrip/config.toml")
    }

    static var defaultDownloads: URL {
        FileManager.default.homeDirectoryForCurrentUser
            .appendingPathComponent("Music/QDL", isDirectory: true)
    }
}

// MARK: - Shell environment

/// Apps launched from Finder get a bare PATH, so add the places Homebrew and pipx install to.
enum Shell {
    static var searchPath: [String] {
        var dirs = ["/opt/homebrew/bin", "/usr/local/bin", NSHomeDirectory() + "/.local/bin"]
        let existing = (ProcessInfo.processInfo.environment["PATH"] ?? "/usr/bin:/bin:/usr/sbin:/sbin")
            .split(separator: ":").map(String.init)
        for d in existing where !dirs.contains(d) { dirs.append(d) }
        return dirs
    }

    static var environment: [String: String] {
        var env = ProcessInfo.processInfo.environment
        env["PATH"] = searchPath.joined(separator: ":")
        env["NO_COLOR"] = "1"
        env["TERM"] = "dumb"
        env["PYTHONUNBUFFERED"] = "1"
        env["PYTHONIOENCODING"] = "utf-8"
        env["COLUMNS"] = "160"
        return env
    }

    static func which(_ name: String) -> String? {
        for dir in searchPath {
            let p = (dir as NSString).appendingPathComponent(name)
            if FileManager.default.isExecutableFile(atPath: p) { return p }
        }
        return nil
    }
}

// MARK: - Process output → lines

final class LineSplitter: @unchecked Sendable {
    private var buffer = Data()
    private let lock = NSLock()
    private let emit: (String) -> Void
    private static let ansi = try! NSRegularExpression(pattern: "\u{1B}\\[[0-9;?]*[ -/]*[@-~]")

    init(emit: @escaping (String) -> Void) { self.emit = emit }

    func feed(_ data: Data) {
        lock.lock()
        buffer.append(data)
        var lines: [String] = []
        while let idx = buffer.firstIndex(where: { $0 == 0x0A || $0 == 0x0D }) {
            let chunk = buffer[buffer.startIndex..<idx]
            lines.append(String(decoding: chunk, as: UTF8.self))
            buffer.removeSubrange(buffer.startIndex...idx)
        }
        lock.unlock()
        for l in lines { send(l) }
    }

    func flush() {
        lock.lock()
        let rest = buffer
        buffer = Data()
        lock.unlock()
        if !rest.isEmpty { send(String(decoding: rest, as: UTF8.self)) }
    }

    private func send(_ raw: String) {
        let range = NSRange(raw.startIndex..., in: raw)
        let clean = Self.ansi.stringByReplacingMatches(in: raw, range: range, withTemplate: "")
            .trimmingCharacters(in: .whitespaces)
        if !clean.isEmpty { emit(clean) }
    }
}

/// Thread-safe line collector for short commands whose output we parse.
final class LineBox: @unchecked Sendable {
    private var lines: [String] = []
    private let lock = NSLock()
    func add(_ s: String) { lock.lock(); lines.append(s); lock.unlock() }
    var all: [String] { lock.lock(); defer { lock.unlock() }; return lines }
}

// MARK: - Process runner

final class ProcessRunner: @unchecked Sendable {
    private var process: Process?
    private let lock = NSLock()

    /// Runs a command, streaming each output line (stdout + stderr) to onLine
    /// from a background thread. Returns the exit code (-1 if it couldn't start).
    func run(_ executable: String, _ arguments: [String],
             onLine: @escaping @Sendable (String) -> Void) async -> Int32 {
        let p = Process()
        p.executableURL = URL(fileURLWithPath: executable)
        p.arguments = arguments
        p.environment = Shell.environment
        p.currentDirectoryURL = Paths.support
        let pipe = Pipe()
        p.standardOutput = pipe
        p.standardError = pipe
        p.standardInput = FileHandle.nullDevice

        let splitter = LineSplitter(emit: onLine)
        let reader = pipe.fileHandleForReading
        reader.readabilityHandler = { handle in
            let data = handle.availableData
            if data.isEmpty {
                handle.readabilityHandler = nil
            } else {
                splitter.feed(data)
            }
        }

        setProcess(p)
        let status: Int32 = await withCheckedContinuation { cont in
            p.terminationHandler = { proc in
                reader.readabilityHandler = nil
                let rest = reader.readDataToEndOfFile()
                if !rest.isEmpty { splitter.feed(rest) }
                splitter.flush()
                cont.resume(returning: proc.terminationStatus)
            }
            do {
                try p.run()
            } catch {
                reader.readabilityHandler = nil
                onLine("Could not start \(executable): \(error.localizedDescription)")
                cont.resume(returning: -1)
            }
        }
        setProcess(nil)
        return status
    }

    /// Runs a command and returns its exit code and output lines.
    func capture(_ executable: String, _ arguments: [String]) async -> (code: Int32, lines: [String]) {
        let box = LineBox()
        let code = await run(executable, arguments) { box.add($0) }
        return (code, box.all)
    }

    func stop() {
        lock.lock()
        let p = process
        lock.unlock()
        if let p, p.isRunning { p.terminate() }
    }

    private func setProcess(_ p: Process?) {
        lock.lock()
        process = p
        lock.unlock()
    }
}

// MARK: - Watching streamrip output for problems

final class IssueTracker: @unchecked Sendable {
    private let lock = NSLock()
    private var _summary: String?
    private var _authProblem = false

    var summary: String? { lock.lock(); defer { lock.unlock() }; return _summary }
    var authProblem: Bool { lock.lock(); defer { lock.unlock() }; return _authProblem }

    func inspect(_ line: String) {
        let l = line.lowercased()
        lock.lock()
        defer { lock.unlock() }

        let looksLikeAuth = l.contains("authenticationerror")
            || l.contains("invalid credentials")
            || l.contains("invalid token")
            || (l.contains("401") && l.contains("unauthorized"))
        if looksLikeAuth {
            _authProblem = true
            _summary = "Qobuz rejected the login — check your token"
            return
        }
        if l.contains("ineligible") {
            _summary = "This account can't download (free or expired subscription?)"
            return
        }
        if _summary == nil && (l.contains("error") || l.contains("traceback") || l.contains("failed")) {
            _summary = String(line.prefix(160))
        }
    }
}

// MARK: - streamrip config editing

enum StreamripConfig {
    static func tomlString(_ s: String) -> String {
        let escaped = s
            .replacingOccurrences(of: "\\", with: "\\\\")
            .replacingOccurrences(of: "\"", with: "\\\"")
        return "\"\(escaped)\""
    }

    static func md5(_ s: String) -> String {
        Insecure.MD5.hash(data: Data(s.utf8)).map { String(format: "%02x", $0) }.joined()
    }

    /// Sets "key = value" lines inside one [section] of a TOML file, keeping
    /// every other line (comments included) exactly as it was.
    static func patch(_ toml: String, section: String, values: [(String, String)]) -> String {
        var lines = toml.components(separatedBy: "\n")
        var inSection = false
        var found = false
        var sectionEnd: Int?
        var seen = Set<String>()

        for i in lines.indices {
            let t = lines[i].trimmingCharacters(in: .whitespaces)
            if t.hasPrefix("[") {
                if inSection && sectionEnd == nil { sectionEnd = i }
                inSection = (t == "[\(section)]")
                if inSection { found = true }
                continue
            }
            guard inSection, !t.hasPrefix("#"), let eq = t.firstIndex(of: "=") else { continue }
            let key = String(t[..<eq]).trimmingCharacters(in: .whitespaces)
            if let value = values.first(where: { $0.0 == key })?.1 {
                lines[i] = "\(key) = \(value)"
                seen.insert(key)
            }
        }

        let missing = values.filter { !seen.contains($0.0) }.map { "\($0.0) = \($0.1)" }
        if !missing.isEmpty {
            if found {
                lines.insert(contentsOf: missing, at: sectionEnd ?? lines.count)
            } else {
                lines.append("")
                lines.append("[\(section)]")
                lines.append(contentsOf: missing)
            }
        }
        return lines.joined(separator: "\n")
    }
}

