import SwiftUI
import AppKit

enum Pane: String { case browse, downloads }

enum PreviewState: Equatable {
    case idle
    case loading(String)
    case ready
    case failed(String)
}

@MainActor
final class AppModel: ObservableObject {
    enum EngineState: Equatable {
        case checking
        case missing
        case installing
        case ready(String)

        var isReady: Bool { if case .ready = self { return true } else { return false } }
    }

    // Browse
    @Published var pane: Pane = .browse
    @Published var linkField = ""
    @Published var previewState: PreviewState = .idle
    @Published var preview: Preview?
    @Published var selected: Set<String> = []
    @Published var cover: NSImage?
    @Published var albumColors: [NSColor] = []
    @Published var recent: [RecentItem] = []
    @Published var flash: String?

    // Downloads + engine
    @Published var jobs: [DownloadJob] = []
    @Published var log: [LogLine] = []
    @Published var showLog = false
    @Published var engine: EngineState = .checking
    @Published var homebrewMissing = false
    @Published var isRunning = false
    @Published var showAccount = false
    @Published var showAppearance = false

    // Saved download settings
    @Published var quality: AudioQuality { didSet { defaults.set(quality.rawValue, forKey: "quality") } }
    @Published var format: OutputFormat { didSet { defaults.set(format.rawValue, forKey: "format") } }
    @Published var folder: URL { didSet { defaults.set(folder.path, forKey: "folder") } }
    @Published var authMethod: AuthMethod { didSet { defaults.set(authMethod.rawValue, forKey: "authMethod") } }
    @Published var accountID: String { didSet { defaults.set(accountID, forKey: "accountID") } }
    @Published var skipRepeats: Bool { didSet { defaults.set(skipRepeats, forKey: "skipRepeats") } }
    @Published var keepFlac: Bool { didSet { defaults.set(keepFlac, forKey: "keepFlac") } }

    // Saved appearance
    @Published var themeChoice: ThemeChoice { didSet { defaults.set(themeChoice.rawValue, forKey: "theme") } }
    @Published var glassStyle: GlassStyle { didSet { defaults.set(glassStyle.rawValue, forKey: "glass") } }
    @Published var accentChoice: AccentChoice { didSet { defaults.set(accentChoice.rawValue, forKey: "accent") } }
    @Published var backgroundChoice: BackgroundChoice { didSet { defaults.set(backgroundChoice.rawValue, forKey: "background") } }
    @Published var density: Density { didSet { defaults.set(density.rawValue, forKey: "density") } }
    @Published var reduceTransparency: Bool { didSet { defaults.set(reduceTransparency, forKey: "reduceTransparency") } }

    private let defaults = UserDefaults.standard
    private let downloadRunner = ProcessRunner()   // the Stop button targets this one
    private let quickRunner = ProcessRunner()      // version checks, previews, conversions
    private var stopRequested = false
    private var previewToken = UUID()

    init() {
        let d = UserDefaults.standard
        quality = AudioQuality(rawValue: d.integer(forKey: "quality")) ?? .hiResMax
        format = OutputFormat(rawValue: d.string(forKey: "format") ?? "") ?? .original
        if let p = d.string(forKey: "folder") {
            folder = URL(fileURLWithPath: p, isDirectory: true)
        } else {
            folder = Paths.defaultDownloads
        }
        authMethod = AuthMethod(rawValue: d.string(forKey: "authMethod") ?? "") ?? .token
        accountID = d.string(forKey: "accountID") ?? ""
        skipRepeats = d.bool(forKey: "skipRepeats")
        keepFlac = d.bool(forKey: "keepFlac")
        themeChoice = ThemeChoice(rawValue: d.string(forKey: "theme") ?? "") ?? .auto
        glassStyle = GlassStyle(rawValue: d.string(forKey: "glass") ?? "") ?? .tinted
        accentChoice = AccentChoice(rawValue: d.string(forKey: "accent") ?? "") ?? .blue
        backgroundChoice = BackgroundChoice(rawValue: d.string(forKey: "background") ?? "") ?? .album
        density = Density(rawValue: d.string(forKey: "density") ?? "") ?? .comfortable
        reduceTransparency = d.bool(forKey: "reduceTransparency")

        let r = downloadRunner
        _ = NotificationCenter.default.addObserver(
            forName: NSApplication.willTerminateNotification, object: nil, queue: nil
        ) { _ in r.stop() }

        Task { await checkEngine() }
    }

    func theme(for scheme: ColorScheme) -> Theme {
        ThemeBuilder.make(isDark: scheme == .dark, glass: glassStyle, reduce: reduceTransparency,
                          accent: accentChoice, background: backgroundChoice, albumColors: albumColors)
    }

    // MARK: Account

    func hasSecret(for method: AuthMethod) -> Bool { defaults.bool(forKey: method.savedFlagKey) }

    var hasCredentials: Bool { !accountID.trimmed.isEmpty && hasSecret(for: authMethod) }

    func saveAccount(method: AuthMethod, account: String, secret: String) {
        authMethod = method
        accountID = account.trimmed
        let s = secret.trimmed
        if !s.isEmpty {
            // streamrip expects the MD5 of the password, so the plain password is never stored.
            let value = method == .token ? s : StreamripConfig.md5(s)
            if Keychain.save(value, account: method.keychainAccount) {
                defaults.set(true, forKey: method.savedFlagKey)
            } else {
                appendLog("Couldn't save to the Keychain.", isError: true)
            }
        }
        objectWillChange.send()
    }

    // MARK: Engine

    func checkEngine() async {
        engine = .checking
        guard let rip = Shell.which("rip") else { engine = .missing; return }
        let result = await quickRunner.capture(rip, ["--version"])
        if result.code == 0 {
            let version = result.lines.last?.split(separator: " ").last.map(String.init) ?? "?"
            engine = .ready(version)
        } else {
            engine = .missing
            result.lines.forEach { appendLog($0) }
        }
    }

    func installEngine() async {
        guard !isRunning else { return }
        isRunning = true
        engine = .installing
        homebrewMissing = false
        appendLog("Installing streamrip, Python 3.12 and ffmpeg with Homebrew. This can take a few minutes.")
        let script = """
        export PATH="/opt/homebrew/bin:/usr/local/bin:$HOME/.local/bin:$PATH"
        export HOMEBREW_NO_AUTO_UPDATE=1
        if ! command -v brew >/dev/null 2>&1; then echo "Homebrew not found."; exit 3; fi
        brew install python@3.12 pipx ffmpeg || exit 1
        PY="$(brew --prefix python@3.12)/bin/python3.12"
        pipx install --force --python "$PY" streamrip
        """
        let code = await downloadRunner.run("/bin/zsh", ["-c", script]) { [weak self] line in
            Task { @MainActor in self?.appendLog(line) }
        }
        if code == 3 { homebrewMissing = true }
        if code != 0 {
            appendLog("Engine install didn't finish (code \(code)).", isError: true)
            showLog = true
        }
        isRunning = false
        await checkEngine()
    }

    func updateEngine() async {
        guard !isRunning else { return }
        isRunning = true
        let script = """
        export PATH="/opt/homebrew/bin:/usr/local/bin:$HOME/.local/bin:$PATH"
        brew install ffmpeg >/dev/null 2>&1 || true
        pipx upgrade streamrip || pipx install --force --python "$(brew --prefix python@3.12)/bin/python3.12" streamrip
        """
        _ = await downloadRunner.run("/bin/zsh", ["-c", script]) { [weak self] line in
            Task { @MainActor in self?.appendLog(line) }
        }
        isRunning = false
        await checkEngine()
    }

    // MARK: Browse

    func openLink(_ text: String? = nil) {
        let raw = text ?? linkField
        guard let link = QobuzLink.parse(raw) else {
            if !raw.trimmed.isEmpty {
                previewState = .failed("That doesn't look like a Qobuz album, track, playlist or artist link.")
            }
            return
        }
        linkField = link.url
        pane = .browse
        if link.kind == "album" || link.kind == "track" {
            Task { await loadPreview(link) }
        } else {
            previewToken = UUID()
            preview = Preview.wholeOnly(link)
            selected = []
            cover = nil
            albumColors = []
            previewState = .ready
        }
    }

    func pasteAndOpen() {
        guard let s = NSPasteboard.general.string(forType: .string) else { return }
        linkField = s.trimmed
        openLink(s)
    }

    func loadPreview(_ link: QobuzLink) async {
        guard engine.isReady, let rip = Shell.which("rip") else {
            previewState = .failed("Install the download engine first — use the button in the sidebar.")
            return
        }
        guard hasCredentials else {
            previewState = .failed("Add your Qobuz account to open links.")
            showAccount = true
            return
        }
        guard let python = Metadata.streamripPython() else {
            previewState = .failed("Couldn't find streamrip's Python. Try QDL → Update Download Engine.")
            return
        }
        let token = UUID()
        previewToken = token
        previewState = .loading(link.kind == "track" ? "Opening track…" : "Opening album…")

        guard await prepareConfig(rip: rip, quality: quality) else {
            previewState = .failed("Couldn't prepare the engine settings.")
            return
        }
        let helper = Metadata.writeHelper()
        let result = await quickRunner.capture(python, [helper.path, Paths.config.path, link.kind, link.id])
        if !isRunning { scrubSecret() }
        guard previewToken == token else { return }

        if let line = result.lines.first(where: { $0.hasPrefix("QDLJSON:") }),
           let data = String(line.dropFirst(8)).data(using: .utf8),
           let obj = (try? JSONSerialization.jsonObject(with: data)) as? [String: Any],
           let p = Metadata.preview(from: obj, link: link) {
            preview = p
            selected = Set(p.tracks.filter(\.streamable).map(\.id))
            previewState = .ready
            addRecent(p)
            await loadCover(p.coverURL, token: token)
        } else {
            let err = result.lines.first(where: { $0.hasPrefix("QDLERR:") }).map { String($0.dropFirst(7)) }
                ?? result.lines.last ?? "Qobuz didn't answer."
            result.lines.filter { !$0.hasPrefix("QDLJSON:") }.forEach { appendLog($0) }
            let lower = err.lowercased()
            if lower.contains("auth") || lower.contains("invalid") || lower.contains("401") {
                previewState = .failed("Qobuz rejected the login. Your token may have expired — update it in Account.")
            } else {
                previewState = .failed(err)
            }
        }
    }

    private func loadCover(_ url: URL?, token: UUID) async {
        cover = nil
        albumColors = []
        guard let url else { return }
        guard let result = try? await URLSession.shared.data(from: url) else { return }
        guard previewToken == token else { return }
        let data = result.0
        cover = NSImage(data: data)
        albumColors = CoverColors.extract(from: data)
    }

    private func addRecent(_ p: Preview) {
        recent.removeAll { $0.link == p.link }
        recent.insert(RecentItem(title: p.title, artist: p.artist, link: p.link, coverURL: p.coverURL), at: 0)
        if recent.count > 8 { recent.removeLast(recent.count - 8) }
    }

    // MARK: Track selection

    func toggle(_ track: PreviewTrack) {
        if selected.contains(track.id) { selected.remove(track.id) } else { selected.insert(track.id) }
    }

    var allSelected: Bool {
        guard let p = preview, !p.tracks.isEmpty else { return false }
        return p.tracks.filter(\.streamable).allSatisfy { selected.contains($0.id) }
    }

    func toggleAll() {
        guard let p = preview else { return }
        selected = allSelected ? [] : Set(p.tracks.filter(\.streamable).map(\.id))
    }

    var selectedTracks: [PreviewTrack] {
        preview?.tracks.filter { selected.contains($0.id) } ?? []
    }

    var selectionSummary: String {
        guard let p = preview else { return "" }
        if p.isWholeOnly { return "The whole \(p.kind) will be downloaded" }
        let chosen = selectedTracks
        let minutes = Double(chosen.reduce(0) { $0 + $1.duration }) / 60
        let mb = minutes * Metadata.megabytesPerMinute(quality: quality, format: format, preview: p)
        let size = mb >= 1000 ? String(format: "%.1f GB", mb / 1000) : "\(Int(mb.rounded())) MB"
        return "\(chosen.count) of \(p.tracks.count) track\(p.tracks.count == 1 ? "" : "s") selected · about \(size)"
    }

    var qualityNote: String {
        let p = preview
        if format == .wav {
            if quality == .mp3 { return "WAV needs a lossless source — pick CD, Hi-Res or Max." }
            return "Downloads FLAC, then converts to WAV at the same bit depth and sample rate."
        }
        if let p, !p.isWholeOnly, p.maxBitDepth > 0, quality.rawValue > p.bestQuality.rawValue, quality != .mp3 {
            return "This release tops out at \(p.bestText), so that's what you'll get."
        }
        switch quality {
        case .mp3: return "MP3 at 320 kbps — smallest files."
        case .cd: return "FLAC at 16-bit / 44.1 kHz — CD quality."
        case .hiRes: return "FLAC at 24-bit up to 96 kHz."
        case .hiResMax: return "The best available, up to 24-bit / 192 kHz."
        }
    }

    private func effectiveQualityText(_ p: Preview) -> String {
        if quality == .mp3 || format == .mp3 { return "MP3" }
        if format == .aac { return "AAC" }
        let q = p.maxBitDepth > 0 ? min(quality.rawValue, p.bestQuality.rawValue) : quality.rawValue
        let res = q >= p.bestQuality.rawValue && p.maxBitDepth > 0 ? p.bestText : (AudioQuality(rawValue: q)?.sub ?? "")
        return "\(res) \(format.short)"
    }

    func downloadSelection() {
        guard let p = preview else { return }
        if format == .wav && quality == .mp3 { return }
        let job: DownloadJob
        if p.isWholeOnly {
            job = DownloadJob(title: p.title, artist: p.artist, coverURL: nil, link: p.link, kind: p.kind,
                              quality: quality, format: format, qualityText: "\(quality.label) \(format.short)",
                              wholeRelease: true, tracks: [])
        } else {
            let chosen = selectedTracks
            guard !chosen.isEmpty else { return }
            let whole = p.kind == "album" && chosen.count == p.tracks.count
            job = DownloadJob(title: p.title, artist: p.artist, coverURL: p.coverURL, link: p.link, kind: p.kind,
                              quality: quality, format: format, qualityText: effectiveQualityText(p),
                              wholeRelease: whole,
                              tracks: chosen.map { JobTrack(id: $0.id, number: $0.number, title: $0.title) })
        }
        jobs.append(job)
        showFlash("Added to Downloads")
        startQueue()
    }

    private func showFlash(_ text: String) {
        flash = text
        Task {
            try? await Task.sleep(nanoseconds: 2_500_000_000)
            if flash == text { flash = nil }
        }
    }

    // MARK: Queue

    var activeCount: Int { jobs.filter { !$0.status.isFinished }.count }

    func startQueue() {
        guard !isRunning, engine.isReady else { return }
        guard hasCredentials else { showAccount = true; return }
        Task { await runQueue() }
    }

    func stop() {
        stopRequested = true
        downloadRunner.stop()
    }

    func retry(_ job: DownloadJob) {
        guard let i = jobs.firstIndex(where: { $0.id == job.id }), jobs[i].status.isFinished else { return }
        for k in jobs[i].tracks.indices where jobs[i].tracks[k].status != .done {
            jobs[i].tracks[k].status = .waiting
        }
        if jobs[i].wholeRelease {
            for k in jobs[i].tracks.indices { jobs[i].tracks[k].status = .waiting }
        }
        jobs[i].status = .queued
        jobs[i].finishedAt = nil
        startQueue()
    }

    func remove(_ job: DownloadJob) { jobs.removeAll { $0.id == job.id && $0.status != .running } }

    func clearFinished() { jobs.removeAll { $0.status.isFinished } }

    private func setTrack(_ jobID: UUID, _ trackID: String, _ status: TrackStatus) {
        guard let i = jobs.firstIndex(where: { $0.id == jobID }),
              let k = jobs[i].tracks.firstIndex(where: { $0.id == trackID }) else { return }
        jobs[i].tracks[k].status = status
    }

    private func setTracks(_ jobID: UUID, where match: (TrackStatus) -> Bool, to status: TrackStatus) {
        guard let i = jobs.firstIndex(where: { $0.id == jobID }) else { return }
        for k in jobs[i].tracks.indices where match(jobs[i].tracks[k].status) {
            jobs[i].tracks[k].status = status
        }
    }

    private func runQueue() async {
        guard let rip = Shell.which("rip") else { engine = .missing; return }
        isRunning = true
        stopRequested = false
        try? FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)

        while !stopRequested, let jIdx = jobs.firstIndex(where: { $0.status == .queued }) {
            let jobID = jobs[jIdx].id
            jobs[jIdx].status = .running
            let job = jobs[jIdx]
            var failures: [String] = []
            var authProblem = false

            if job.wholeRelease || job.tracks.isEmpty {
                setTracks(jobID, where: { $0 == .waiting }, to: .running)
                let r = await runRip(rip, job: job, target: ["url", job.link])
                if r.auth { authProblem = true }
                if let f = r.failure { failures.append(f) }
                var outcome = TrackStatus.done
                if stopRequested {
                    outcome = .cancelled
                } else if let f = r.failure {
                    outcome = .failed(f)
                }
                setTracks(jobID, where: { $0 == .running }, to: outcome)
            } else {
                for t in job.tracks where t.status == .waiting {
                    if stopRequested { break }
                    setTrack(jobID, t.id, .running)
                    let r = await runRip(rip, job: job, target: ["id", "qobuz", "track", t.id])
                    if stopRequested { setTrack(jobID, t.id, .cancelled); break }
                    if let f = r.failure {
                        failures.append(f)
                        setTrack(jobID, t.id, .failed(f))
                    } else {
                        setTrack(jobID, t.id, .done)
                    }
                    if r.auth { authProblem = true; break }
                }
                if stopRequested || authProblem {
                    setTracks(jobID, where: { $0 == .waiting }, to: .cancelled)
                }
            }

            guard let i = jobs.firstIndex(where: { $0.id == jobID }) else { continue }
            jobs[i].finishedAt = Date()
            if stopRequested {
                jobs[i].status = .cancelled
            } else if authProblem {
                jobs[i].status = .failed("Qobuz rejected the login — your token may have expired")
                showAccount = true
                break
            } else if failures.isEmpty {
                jobs[i].status = .done
            } else if failures.count >= max(1, job.tracks.count) || job.wholeRelease {
                jobs[i].status = .failed(failures[0])
            } else {
                jobs[i].status = .warning("\(failures.count) of \(job.tracks.count) tracks failed")
            }
        }

        if case .loading = previewState {} else { scrubSecret() }
        isRunning = false
    }

    private struct RipResult {
        var failure: String?
        var auth: Bool
    }

    private func runRip(_ rip: String, job: DownloadJob, target: [String]) async -> RipResult {
        guard await prepareConfig(rip: rip, quality: job.quality) else {
            return RipResult(failure: "Couldn't prepare the engine settings", auth: false)
        }
        let started = Date()
        var args = ["--config-path", Paths.config.path,
                    "--folder", folder.path,
                    "--quality", "\(job.quality.rawValue)",
                    "--no-progress"]
        if !skipRepeats { args.append("--no-db") }
        if let codec = job.format.codecArgument { args += ["--codec", codec] }
        args += target
        appendLog("▶ \(job.title) — \(target.joined(separator: " "))")

        let issues = IssueTracker()
        let code = await downloadRunner.run(rip, args) { [weak self] line in
            issues.inspect(line)
            Task { @MainActor in self?.appendLog(line) }
        }
        if stopRequested { return RipResult(failure: nil, auth: false) }
        if issues.authProblem { return RipResult(failure: issues.summary, auth: true) }
        if code != 0 { return RipResult(failure: issues.summary ?? "Stopped with code \(code)", auth: false) }

        let produced = newAudioFiles(since: started)
        if produced.isEmpty, let note = issues.summary {
            return RipResult(failure: note, auth: false)
        }
        if job.format == .wav {
            if let problem = await convertToWav(produced.filter { $0.pathExtension.lowercased() == "flac" }) {
                return RipResult(failure: problem, auth: false)
            }
        }
        return RipResult(failure: nil, auth: false)
    }

    private func newAudioFiles(since: Date) -> [URL] {
        let exts: Set<String> = ["flac", "m4a", "mp3", "wav", "opus", "ogg", "aif", "aiff"]
        let keys: [URLResourceKey] = [.contentModificationDateKey, .isRegularFileKey]
        guard let walker = FileManager.default.enumerator(at: folder, includingPropertiesForKeys: keys,
                                                          options: [.skipsHiddenFiles]) else { return [] }
        let cutoff = since.addingTimeInterval(-2)
        var out: [URL] = []
        for case let url as URL in walker {
            guard exts.contains(url.pathExtension.lowercased()) else { continue }
            if let d = (try? url.resourceValues(forKeys: [.contentModificationDateKey]))?.contentModificationDate,
               d >= cutoff {
                out.append(url)
            }
        }
        return out
    }

    /// Converts FLAC files to WAV at their own bit depth and sample rate (no resampling).
    /// Returns a problem description, or nil when everything converted.
    private func convertToWav(_ files: [URL]) async -> String? {
        guard !files.isEmpty else { return nil }
        guard let ffmpeg = Shell.which("ffmpeg") else {
            return "ffmpeg isn't installed — use QDL → Update Download Engine"
        }
        let ffprobe = Shell.which("ffprobe")
        for flac in files {
            var depth = 24
            if let ffprobe {
                let probe = await quickRunner.capture(ffprobe, ["-v", "error", "-select_streams", "a:0",
                                                                "-show_entries", "stream=bits_per_raw_sample",
                                                                "-of", "default=nw=1:nk=1", flac.path])
                if let v = probe.lines.compactMap({ Int($0) }).first, v > 0 { depth = v }
            }
            let codec = depth <= 16 ? "pcm_s16le" : (depth <= 24 ? "pcm_s24le" : "pcm_s32le")
            let wav = flac.deletingPathExtension().appendingPathExtension("wav")
            appendLog("Converting \(flac.lastPathComponent) → WAV, \(depth)-bit at its original sample rate")
            let code = await quickRunner.run(ffmpeg, ["-hide_banner", "-loglevel", "error", "-y",
                                                       "-i", flac.path, "-map", "0:a:0", "-map_metadata", "0",
                                                       "-c:a", codec, "-rf64", "auto", wav.path]) { [weak self] line in
                Task { @MainActor in self?.appendLog(line, isError: true) }
            }
            if code != 0 { return "WAV conversion failed for \(flac.lastPathComponent)" }
            if !keepFlac { try? FileManager.default.trashItem(at: flac, resultingItemURL: nil) }
        }
        return nil
    }

    /// Makes sure QDL's private streamrip config exists, then writes the account + quality into it.
    private func prepareConfig(rip: String, quality: AudioQuality) async -> Bool {
        let fm = FileManager.default
        let path = Paths.config

        if !fm.fileExists(atPath: path.path) {
            // streamrip creates a default config when the one it's pointed at doesn't exist.
            _ = await quickRunner.capture(rip, ["--config-path", path.path, "config", "path"])
            if !fm.fileExists(atPath: path.path) {
                _ = await quickRunner.capture(rip, ["config", "path"])
                if fm.fileExists(atPath: Paths.defaultStreamripConfig.path) {
                    try? fm.copyItem(at: Paths.defaultStreamripConfig, to: path)
                }
            }
        }

        guard var toml = try? String(contentsOf: path, encoding: .utf8) else {
            appendLog("Couldn't create the engine settings file at \(path.path).", isError: true)
            return false
        }
        guard let secret = Keychain.read(authMethod.keychainAccount), !secret.isEmpty else {
            appendLog("Add your Qobuz account first.", isError: true)
            showAccount = true
            return false
        }

        toml = StreamripConfig.patch(toml, section: "qobuz", values: [
            ("quality", "\(quality.rawValue)"),
            ("use_auth_token", authMethod == .token ? "true" : "false"),
            ("email_or_userid", StreamripConfig.tomlString(accountID.trimmed)),
            ("password_or_token", StreamripConfig.tomlString(secret)),
        ])
        toml = StreamripConfig.patch(toml, section: "filepaths", values: [("add_singles_to_folder", "true")])
        toml = StreamripConfig.patch(toml, section: "misc", values: [("check_for_updates", "false")])

        do {
            try toml.write(to: path, atomically: true, encoding: .utf8)
            try fm.setAttributes([.posixPermissions: 0o600], ofItemAtPath: path.path)
        } catch {
            appendLog("Couldn't write engine settings: \(error.localizedDescription)", isError: true)
            return false
        }
        return true
    }

    /// Removes the token/password from the config file when nothing is using it.
    private func scrubSecret() {
        let path = Paths.config
        guard let toml = try? String(contentsOf: path, encoding: .utf8) else { return }
        let cleaned = StreamripConfig.patch(toml, section: "qobuz", values: [("password_or_token", "\"\"")])
        try? cleaned.write(to: path, atomically: true, encoding: .utf8)
    }

    // MARK: Folder

    func chooseFolder() {
        let panel = NSOpenPanel()
        panel.canChooseDirectories = true
        panel.canChooseFiles = false
        panel.canCreateDirectories = true
        panel.allowsMultipleSelection = false
        panel.prompt = "Choose"
        panel.directoryURL = folder
        if panel.runModal() == .OK, let url = panel.url { folder = url }
    }

    func revealFolder() {
        try? FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
        NSWorkspace.shared.open(folder)
    }

    var folderDisplay: String {
        let home = NSHomeDirectory()
        let p = folder.path
        return p.hasPrefix(home) ? "~" + String(p.dropFirst(home.count)) : p
    }

    // MARK: Log

    func appendLog(_ text: String, isError: Bool? = nil) {
        let lower = text.lowercased()
        let err = isError ?? (lower.contains("error") || lower.contains("traceback") || lower.contains("failed"))
        log.append(LogLine(text: text, isError: err))
        if log.count > 3000 { log.removeFirst(log.count - 3000) }
    }
}

