import SwiftUI
import AppKit

// MARK: - Root

struct RootView: View {
    @EnvironmentObject var model: AppModel
    @Environment(\.colorScheme) private var scheme

    var body: some View {
        let theme = model.theme(for: scheme)
        ZStack {
            AuroraBackground()
            VStack(spacing: 10) {
                TopBar()
                HStack(alignment: .top, spacing: 12) {
                    Sidebar()
                        .frame(width: 232)
                    Group {
                        switch model.pane {
                        case .browse: BrowseView()
                        case .downloads: DownloadsView()
                        }
                    }
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                }
                .padding(.horizontal, 12)
                .padding(.bottom, 12)
            }
        }
        .environment(\.qdl, theme)
        .foregroundStyle(theme.text)
        .tint(theme.accent)
        .preferredColorScheme(model.themeChoice.colorScheme)
        .sheet(isPresented: $model.showAccount) {
            AccountSheet()
                .environmentObject(model)
                .environment(\.qdl, theme)
        }
    }
}

// MARK: - Shared pieces

struct Segmented<T: Hashable>: View {
    @Environment(\.qdl) private var t
    let options: [T]
    @Binding var selection: T
    let label: (T) -> String
    var sub: ((T) -> String)? = nil
    var height: CGFloat = 30

    var body: some View {
        HStack(spacing: 2) {
            ForEach(options, id: \.self) { o in
                let on = o == selection
                Button {
                    withAnimation(.spring(response: 0.35, dampingFraction: 0.8)) { selection = o }
                } label: {
                    VStack(spacing: 0) {
                        Text(label(o)).font(.system(size: 13, weight: .semibold))
                        if let sub {
                            Text(sub(o)).font(.system(size: 10.5))
                        }
                    }
                    .foregroundStyle(on ? t.text : t.sub)
                    .frame(maxWidth: .infinity, minHeight: height)
                    .padding(.horizontal, 8)
                    .background {
                        if on {
                            Capsule()
                                .fill(t.segOn)
                                .shadow(color: .black.opacity(t.isDark ? 0 : 0.12), radius: 2, y: 1)
                        }
                    }
                    .contentShape(Capsule())
                }
                .buttonStyle(.plain)
                .accessibilityAddTraits(on ? .isSelected : [])
            }
        }
        .padding(3)
        .background(Capsule().fill(t.control))
    }
}

struct CoverView: View {
    var image: NSImage? = nil
    var url: URL? = nil
    let size: CGFloat
    let radius: CGFloat

    var body: some View {
        Group {
            if let image {
                Image(nsImage: image).resizable().aspectRatio(contentMode: .fill)
            } else if let url {
                AsyncImage(url: url) { img in
                    img.resizable().aspectRatio(contentMode: .fill)
                } placeholder: {
                    placeholder
                }
            } else {
                placeholder
            }
        }
        .frame(width: size, height: size)
        .clipShape(RoundedRectangle(cornerRadius: radius, style: .continuous))
        .overlay(RoundedRectangle(cornerRadius: radius, style: .continuous).strokeBorder(Color.white.opacity(0.12)))
        .accessibilityHidden(true)
    }

    private var placeholder: some View {
        ZStack {
            LinearGradient(colors: [Color(hex: 0x2E6E86), Color(hex: 0x0E2233)], startPoint: .top, endPoint: .bottom)
            Image(systemName: "music.note")
                .font(.system(size: size * 0.3, weight: .light))
                .foregroundStyle(Color.white.opacity(0.55))
        }
    }
}

struct Badge: View {
    @Environment(\.qdl) private var t
    let text: String
    var gold = false

    var body: some View {
        Text(text)
            .font(.system(size: 11.5, weight: .semibold))
            .padding(.horizontal, 10)
            .padding(.vertical, 4)
            .foregroundStyle(gold ? t.badgeText : t.text)
            .background(Capsule().fill(gold ? t.badgeFill : t.control))
    }
}

struct AccentButton: View {
    @Environment(\.qdl) private var t
    let title: String
    let icon: String
    var enabled = true
    let action: () -> Void

    var body: some View {
        Button(action: action) {
            Label(title, systemImage: icon)
                .font(.system(size: 14, weight: .semibold))
                .padding(.horizontal, 20)
                .frame(height: 44)
                .foregroundStyle(enabled ? t.buttonText : t.sub)
                .background(Capsule().fill(enabled ? t.button : t.control))
                .overlay(Capsule().strokeBorder(Color.white.opacity(enabled ? 0.18 : 0)))
                .contentShape(Capsule())
        }
        .buttonStyle(.plain)
        .disabled(!enabled)
    }
}

// MARK: - Top bar

struct TopBar: View {
    @EnvironmentObject var model: AppModel
    @Environment(\.qdl) private var t

    var body: some View {
        HStack(spacing: 10) {
            HStack(spacing: 8) {
                Image(systemName: "link")
                    .font(.system(size: 13))
                    .foregroundStyle(t.sub)
                TextField("Paste a Qobuz album, track, playlist or artist link", text: $model.linkField)
                    .textFieldStyle(.plain)
                    .font(.system(size: 13))
