struct AlbumHeader: View {
    @EnvironmentObject var model: AppModel
    @Environment(\.qdl) private var t
    let preview: Preview

    private var meta: String {
        var parts: [String] = []
        if let y = preview.year { parts.append(y) }
        if let g = preview.genre { parts.append(g) }
        if !preview.tracks.isEmpty {
            parts.append("\(preview.tracks.count) track\(preview.tracks.count == 1 ? "" : "s")")
            parts.append("\(max(1, preview.totalSeconds / 60)) min")
        }
        if let l = preview.label { parts.append(l) }
        return parts.joined(separator: " · ")
    }

    private var rateText: String {
        let r = preview.maxSampleRate
        return r.rounded() == r ? String(Int(r)) : String(format: "%.1f", r)
    }

    var body: some View {
        HStack(alignment: .bottom, spacing: 26) {
            CoverView(image: model.cover, url: preview.coverURL, size: 220, radius: 14)
                .shadow(color: .black.opacity(0.4), radius: 24, y: 14)
            VStack(alignment: .leading, spacing: 9) {
                Text(preview.kind.uppercased())
                    .font(.system(size: 11.5, weight: .semibold))
                    .foregroundStyle(t.sub)
                Text(preview.title)
                    .font(.system(size: 38, weight: .bold))
                    .lineLimit(3)
                Text(preview.artist)
                    .font(.system(size: 18, weight: .medium))
                    .foregroundStyle(t.accentText)
                if !meta.isEmpty {
                    Text(meta).font(.system(size: 13)).foregroundStyle(t.sub)
                }
                HStack(spacing: 8) {
                    if preview.maxBitDepth > 0 {
                        Badge(text: (preview.maxBitDepth >= 24 ? "Hi-Res · " : "CD · ") + "\(preview.maxBitDepth)-bit / \(rateText) kHz", gold: preview.maxBitDepth >= 24)
                    }
                    if preview.discCount > 1 {
                        Badge(text: "\(preview.discCount) discs")
                    }
                }
                .padding(.top, 2)
            }
            Spacer(minLength: 0)
        }
    }
}

