struct JobCard: View {
    @EnvironmentObject var model: AppModel
    @Environment(\.qdl) private var t
    let job: DownloadJob
    @State private var expanded = true

    private var statusLine: String {
        switch job.status {
        case .queued: return "Waiting to start"
        case .running:
            if job.wholeRelease || job.tracks.isEmpty { return "Downloading the whole \(job.kind)…" }
            let current = min(job.tracks.count, job.tracks.filter { $0.status == .done }.count + 1)
            return "Track \(current) of \(job.tracks.count)"
        case .done: return job.tracks.isEmpty ? "Done" : "Done · \(job.tracks.count) track\(job.tracks.count == 1 ? "" : "s")"
        case .warning(let m): return m
        case .failed(let m): return m
        case .cancelled: return "Stopped"
        }
    }

    private var statusColor: Color {
        switch job.status {
        case .done: return t.ok
        case .warning, .failed: return t.warn
        default: return t.sub
        }
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 0) {
            HStack(spacing: 16) {
                CoverView(url: job.coverURL, size: 64, radius: 8)
                VStack(alignment: .leading, spacing: 6) {
                    HStack(spacing: 8) {
                        Text(job.title).font(.system(size: 15, weight: .semibold)).lineLimit(1)
                        Text(job.artist).font(.system(size: 13)).foregroundStyle(t.sub).lineLimit(1)
                        Badge(text: job.qualityText, gold: true)
                    }
                    Text(statusLine)
                        .font(.system(size: 12.5))
                        .foregroundStyle(statusColor)
                        .lineLimit(2)
                    if job.status == .running {
                        if job.wholeRelease || job.tracks.isEmpty {
                            ProgressView().progressViewStyle(.linear)
                        } else {
                            ProgressView(value: job.progress).progressViewStyle(.linear)
                        }
                    }
                }
                Spacer(minLength: 8)
                actions
            }
            .padding(16)

            if !job.tracks.isEmpty && !job.wholeRelease {
                DisclosureGroup(isExpanded: $expanded) {
                    VStack(spacing: 0) {
                        ForEach(job.tracks) { track in
                            JobTrackRow(track: track)
                        }
                    }
                    .padding(.top, 6)
                } label: {
                    Text("\(job.tracks.count) track\(job.tracks.count == 1 ? "" : "s")")
                        .font(.system(size: 12))
                        .foregroundStyle(t.sub)
                }
                .padding(.horizontal, 16)
                .padding(.bottom, 12)
            }
        }
        .glass(16)
    }

    @ViewBuilder private var actions: some View {
        HStack(spacing: 8) {
            switch job.status {
            case .running:
                Button {
                    model.stop()
                } label: {
                    Image(systemName: "xmark").frame(width: 30, height: 30)
                }
                .help("Stop")
                .accessibilityLabel("Stop")
            case .queued:
                Button("Remove") { model.remove(job) }
            case .done:
                Button("Show in Finder") { model.revealFolder() }
                Button {
                    model.remove(job)
                } label: {
                    Image(systemName: "xmark").frame(width: 22, height: 22)
                }
                .help("Remove from list")
                .accessibilityLabel("Remove from list")
            case .warning, .failed, .cancelled:
                Button("Retry") { model.retry(job) }
                    .buttonStyle(.borderedProminent)
                Button {
                    model.remove(job)
                } label: {
                    Image(systemName: "xmark").frame(width: 22, height: 22)
                }
                .help("Remove from list")
                .accessibilityLabel("Remove from list")
            }
        }
    }
}

struct JobTrackRow: View {
    @Environment(\.qdl) private var t
    let track: JobTrack

    var body: some View {
        HStack(spacing: 10) {
            Group {
                switch track.status {
                case .done:
                    Image(systemName: "checkmark.circle.fill").foregroundStyle(t.ok)
                case .running:
                    ProgressView().controlSize(.small)
                case .failed:
                    Image(systemName: "exclamationmark.circle.fill").foregroundStyle(t.warn)
                case .cancelled:
                    Image(systemName: "slash.circle").foregroundStyle(t.faint)
                case .waiting:
                    Image(systemName: "circle").foregroundStyle(t.faint)
                }
            }
            .frame(width: 18)
            Text("\(track.number)")
                .font(.system(size: 12).monospacedDigit())
                .foregroundStyle(t.faint)
                .frame(width: 24, alignment: .leading)
            Text(track.title)
                .font(.system(size: 13, weight: track.status == .running ? .semibold : .regular))
                .lineLimit(1)
            Spacer()
            Text(trailing)
                .font(.system(size: 12))
                .foregroundStyle(isFailed ? t.warn : t.sub)
                .lineLimit(1)
        }
        .frame(minHeight: 30)
    }

    private var isFailed: Bool { if case .failed = track.status { return true } else { return false } }

    private var trailing: String {
        switch track.status {
        case .done: return "Done"
        case .running: return "Downloading"
        case .waiting: return "Waiting"
        case .cancelled: return "Stopped"
        case .failed(let m): return m
        }
    }
}

