                            model.accentChoice = a
                        } label: {
                            Circle()
                                .fill(accentSwatch(a))
                                .frame(width: 24, height: 24)
                                .overlay(Circle().strokeBorder(Color.white.opacity(0.25)))
                                .padding(3)
                                .overlay(Circle().strokeBorder(model.accentChoice == a ? t.accent : Color.clear, lineWidth: 2))
                                .frame(width: 38, height: 38)
                                .contentShape(Circle())
                        }
                        .buttonStyle(.plain)
                        .help(a.label)
                        .accessibilityLabel(a.label)
                        .accessibilityAddTraits(model.accentChoice == a ? .isSelected : [])
                    }
                }
            }

            section("Track list") {
                Segmented(options: Density.allCases, selection: $model.density, label: { $0.label })
            }

            Divider()

            Toggle(isOn: $model.reduceTransparency) {
                VStack(alignment: .leading, spacing: 2) {
                    Text("Reduce transparency").font(.system(size: 13, weight: .medium))
                    Text("Solid panels, like the macOS accessibility setting.")
                        .font(.system(size: 11))
                        .foregroundStyle(t.sub)
                }
            }
            .toggleStyle(.switch)
        }
        .padding(20)
        .frame(width: 360)
        .foregroundStyle(t.text)
    }

    private var backgroundNote: String {
        switch model.backgroundChoice {
        case .album: return "Album colours — follows each cover."
        case .neutral: return "Neutral — a quiet backdrop."
        default: return "\(model.backgroundChoice.label) — palette from hishamalfar.com."
        }
    }

    @ViewBuilder
    private func section<C: View>(_ title: String, @ViewBuilder _ content: () -> C) -> some View {
        VStack(alignment: .leading, spacing: 8) {
            Text(title).font(.system(size: 12, weight: .semibold)).foregroundStyle(t.sub)
            content()
        }
    }

    private func caption(_ text: String) -> some View {
        Text(text).font(.system(size: 11)).foregroundStyle(t.sub)
    }

    private func themeSwatch(_ c: ThemeChoice) -> LinearGradient {
        let light = Color(hex: 0xF2F2F7)
        let dark = Color(hex: 0x1C1C1E)
        switch c {
        case .auto:
            return LinearGradient(stops: [.init(color: light, location: 0), .init(color: light, location: 0.5),
                                          .init(color: dark, location: 0.5), .init(color: dark, location: 1)],
                                  startPoint: .topLeading, endPoint: .bottomTrailing)
        case .light: return LinearGradient(colors: [light, light], startPoint: .top, endPoint: .bottom)
        case .dark: return LinearGradient(colors: [dark, dark], startPoint: .top, endPoint: .bottom)
        }
    }

    private func backgroundSwatch(_ b: BackgroundChoice) -> LinearGradient {
        switch b {
        case .album:
            if model.albumColors.count >= 3 {
                return LinearGradient(colors: model.albumColors.prefix(3).map { Color(nsColor: $0) },
                                      startPoint: .topLeading, endPoint: .bottomTrailing)
            }
            return Palettes.albumFallback.gradient
        case .neutral:
            return LinearGradient(colors: t.isDark ? [Color(hex: 0x3A3550), Color(hex: 0x24324A)]
                                                   : [Color(hex: 0xE6D9F2), Color(hex: 0xC9D6F0)],
                                  startPoint: .topLeading, endPoint: .bottomTrailing)
        default:
            return Palettes.all[b]?.gradient
                ?? LinearGradient(colors: [.gray, .gray], startPoint: .top, endPoint: .bottom)
        }
    }

    private func accentSwatch(_ a: AccentChoice) -> LinearGradient {
        if a == .match {
            if let p = Palettes.all[model.backgroundChoice] { return p.gradient }
            return backgroundSwatch(.album)
        }
        let s = SystemAccent.all[a] ?? SystemAccent.all[.blue]!
        let c = t.isDark ? s.dark : s.light
        return LinearGradient(colors: [c, c], startPoint: .top, endPoint: .bottom)
    }
}

