import Foundation

/// Reads album / track details from Qobuz through the installed streamrip,
/// so it uses the same login, app ID and secrets as the downloads.
enum Metadata {
    static let helperScript = """
    import asyncio, json, sys

    async def main():
        from streamrip.config import Config
        try:
            from streamrip.client import QobuzClient
        except ImportError:
            from streamrip.client.qobuz import QobuzClient
        cfg = Config(sys.argv[1])
        client = QobuzClient(cfg)
        try:
            await client.login()
            meta = await client.get_metadata(sys.argv[3], sys.argv[2])
            print("QDLJSON:" + json.dumps(meta), flush=True)
        finally:
            session = getattr(client, "session", None)
            if session is not None:
                try:
                    await session.close()
                except Exception:
                    pass

    try:
        asyncio.run(main())
    except Exception as e:
        print("QDLERR:" + type(e).__name__ + ": " + str(e), flush=True)
        sys.exit(1)
    """

    /// The Python inside streamrip's own environment (pipx), found from the rip command.
    static func streamripPython() -> String? {
        guard let rip = Shell.which("rip") else { return nil }
        let resolved = URL(fileURLWithPath: rip).resolvingSymlinksInPath()
        let sibling = resolved.deletingLastPathComponent().appendingPathComponent("python").path
        if FileManager.default.isExecutableFile(atPath: sibling) { return sibling }
        if let text = try? String(contentsOfFile: resolved.path, encoding: .utf8), text.hasPrefix("#!"),
           let first = text.split(separator: "\n").first {
            let interpreter = String(first.dropFirst(2)).trimmed
            if FileManager.default.isExecutableFile(atPath: interpreter) { return interpreter }
        }
        return nil
    }

    static func writeHelper() -> URL {
        let url = Paths.support.appendingPathComponent("qdl_meta.py")
        try? helperScript.write(to: url, atomically: true, encoding: .utf8)
        return url
    }

    // MARK: Parsing Qobuz JSON

    static func int(_ v: Any?) -> Int {
        if let i = v as? Int { return i }
        if let d = v as? Double { return Int(d) }
        if let s = v as? String { return Int(s) ?? Int(Double(s) ?? 0) }
        return 0
    }

    static func double(_ v: Any?) -> Double {
        if let d = v as? Double { return d }
        if let i = v as? Int { return Double(i) }
        if let s = v as? String { return Double(s) ?? 0 }
        return 0
    }

    static func string(_ v: Any?) -> String? {
        if let s = v as? String, !s.isEmpty { return s }
        if let i = v as? Int { return String(i) }
        return nil
    }

    static func name(_ v: Any?) -> String? {
        (v as? [String: Any]).flatMap { string($0["name"]) }
    }

    static func cover(_ album: [String: Any]?) -> URL? {
        guard let img = album?["image"] as? [String: Any] else { return nil }
        for key in ["large", "extralarge", "medium", "small", "thumbnail"] {
            if let s = string(img[key]), let u = URL(string: s) { return u }
        }
        return nil
    }

    static func track(_ d: [String: Any], albumArtist: String?) -> PreviewTrack? {
        guard let id = string(d["id"]) else { return nil }
        var title = string(d["title"]) ?? "Untitled"
        if let version = string(d["version"]), !title.lowercased().contains(version.lowercased()) {
            title += " (\(version))"
        }
        let performer = name(d["performer"])
        return PreviewTrack(
            id: id,
            number: int(d["track_number"]),
            disc: max(1, int(d["media_number"])),
            title: title,
            artist: performer == albumArtist ? nil : performer,
            duration: int(d["duration"]),
            bitDepth: int(d["maximum_bit_depth"]),
            sampleRate: double(d["maximum_sampling_rate"]),
            streamable: (d["streamable"] as? Bool) ?? true,
            explicit: (d["parental_warning"] as? Bool) ?? false
        )
    }

    static func preview(from json: [String: Any], link: QobuzLink) -> Preview? {
        if link.kind == "album" {
            let artist = name(json["artist"]) ?? "Unknown artist"
            let items = ((json["tracks"] as? [String: Any])?["items"] as? [[String: Any]]) ?? []
            let tracks = items.compactMap { track($0, albumArtist: artist) }
            var title = string(json["title"]) ?? "Untitled album"
            if let version = string(json["version"]) { title += " (\(version))" }
            return Preview(
                kind: "album", id: link.id, link: link.url, title: title, artist: artist,
                year: string(json["release_date_original"]).map { String($0.prefix(4)) },
                genre: name(json["genre"]), label: name(json["label"]), coverURL: cover(json),
                maxBitDepth: int(json["maximum_bit_depth"]), maxSampleRate: double(json["maximum_sampling_rate"]),
                tracks: tracks, isWholeOnly: false)
        }
        if link.kind == "track" {
            let album = json["album"] as? [String: Any]
            let artist = name(json["performer"]) ?? name(album?["artist"]) ?? "Unknown artist"
            guard let t = track(json, albumArtist: artist) else { return nil }
            return Preview(
                kind: "track", id: link.id, link: link.url, title: t.title, artist: artist,
                year: string(album?["release_date_original"]).map { String($0.prefix(4)) },
                genre: name(album?["genre"]), label: name(album?["label"]), coverURL: cover(album),
                maxBitDepth: t.bitDepth, maxSampleRate: t.sampleRate, tracks: [t], isWholeOnly: false)
        }
        return nil
    }

    /// Rough size in MB per minute for a quality / format, capped by what the release offers.
    static func megabytesPerMinute(quality: AudioQuality, format: OutputFormat, preview: Preview) -> Double {
        if format == .aac { return 1.9 }
        if format == .mp3 || quality == .mp3 { return 2.4 }
        let effective = min(quality.rawValue, preview.bestQuality.rawValue)
        let depth: Double
        let rate: Double
        switch effective {
        case 2: depth = 16; rate = 44.1
        case 3: depth = 24; rate = min(96, max(44.1, preview.maxSampleRate))
        default: depth = 24; rate = max(44.1, preview.maxSampleRate)
        }
        // WAV is raw PCM; FLAC is roughly 60% of it.
        let kbps = depth * rate * 2 * (format == .wav ? 1.0 : 0.6)
        return kbps * 60 / 8 / 1000
    }
}

